import { useEffect, useMemo, useState } from 'react';
import { FlatList, Modal, Pressable, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';
import { initializeTakaiLaborNotebook } from '../../data';
import { tokens } from '../../theme/tokens';
import { AmountSummary, AppShell, ConfirmActionSheet, DatePickerField, FeedbackToast, FieldCard, FormFeedback, GardenAccent, IconDisc, LedgerListCard, LedgerListRow, LedgerRowText, LedgerTrailing, MultiSearchPickerSheet, PickerField, PrimaryButton, ScreenSkeleton, SearchPickerSheet, SectionHeader, StatusChip, TopBar, type BottomTabKey } from '../../ui';
import type { LaborV2Adapter } from './previewV2Adapter';
import type { LaborV2OpenContractBatch, LaborV2PersonDetail, LaborV2ReadModel, LaborV2TaskDetail, LaborV2WorkListFilters, LaborWorker, LaborWorkerAdvance } from './types';
import { selectLaborWebProofScenario, selectLaborWebProofScreen, selectLaborWebProofVisual } from './webProofVisual';
import { LaborRecordGroupEditor } from './LaborRecordGroupEditor';
import { PlotManagement } from './PlotManagement';

type Tab = 'today' | 'work' | 'record' | 'payment' | 'people';
type Kind = 'daily' | 'hourly' | 'contract';
export type Ready = { adapter: LaborV2Adapter; model: LaborV2ReadModel; workers: LaborWorker[]; openContracts: LaborV2OpenContractBatch[]; advances: LaborWorkerAdvance[]; date: string };
const tabTitle: Record<Tab, string> = { today: 'วันนี้', work: 'งาน', record: 'บันทึกงาน', payment: 'จ่ายเงิน', people: 'คน' };
const helpText: Record<Tab, string> = { today: 'ดูงานวันนี้และค่าแรงค้างจ่าย แล้วกดไปยังหน้าที่ต้องการได้ทันที', work: 'กดวันที่ในปฏิทินเพื่อดูงานของวันนั้น หรือเปิดรายการงานทั้งหมดเพื่อค้นหาและกรอง', record: 'เลือกคนหรือชุดงานก่อน เติมงานที่ทำวันนี้ แล้วเลือกวิธีคิดค่าแรง', payment: 'เลือกค่าแรงค้างจ่ายก่อน แล้วบันทึกเงินที่จ่าย โบนัส หรือการหักเงินเบิก', people: 'แตะชื่อเพื่อดูประวัติ แก้ไขข้อมูล หรือเก็บรายชื่อโดยไม่ลบประวัติ' };
const todayKey = () => new Date().toISOString().slice(0, 10);
const baht = (satang: number) => `${new Intl.NumberFormat('th-TH', { maximumFractionDigits: 0 }).format(satang / 100)} บาท`;
const personName = (workers: LaborWorker[], id: string | null) => workers.find((item) => item.id === id)?.displayName ?? 'ประวัติเดิม';

export function LaborMvpApp() {
  const visual = selectLaborWebProofVisual(); const [tab, setTab] = useState<Tab>(() => selectLaborWebProofScreen() ?? 'today'); const [ready, setReady] = useState<Ready | null>(null); const [message, setMessage] = useState<string | null>(null); const [retry, setRetry] = useState(0); const [paymentPersonId, setPaymentPersonId] = useState<string | null>(null); const [plotRoute, setPlotRoute] = useState(false);
  const load = async (adapter?: LaborV2Adapter) => { const current = adapter ?? ready?.adapter; if (!current) return; const [model, workers, openContracts, advances] = await Promise.all([current.getReadModel(), current.workers.list(true), current.contracts.listOpen(), current.personFinance.listAdvances()]); setReady({ adapter: current, model, workers, openContracts, advances, date: todayKey() }); };
  useEffect(() => { let alive = true; void initializeTakaiLaborNotebook().then(async (adapter) => { const [model, workers, openContracts, advances] = await Promise.all([adapter.getReadModel(), adapter.workers.list(true), adapter.contracts.listOpen(), adapter.personFinance.listAdvances()]); const fixtureDate = [...model.tasks].map((item) => item.workDate).sort().at(-1); if (alive) setReady({ adapter, model, workers, openContracts, advances, date: adapter.mode === 'proof' && fixtureDate ? fixtureDate : todayKey() }); }).catch(() => alive && setMessage('เปิดสมุดงานไม่สำเร็จ')); return () => { alive = false; }; }, [retry]);
  if (!ready) return <ScreenSkeleton lines={4} />;
  const props = { ready, refresh: () => load(), notify: setMessage };
  if (plotRoute) return <View style={styles.root}><AppShell keyboardAware showTabs={false} variant="detail"><TopBar subtitle="จัดการแปลง" title="TAKAI" variant="default" onInfoPress={() => setMessage('แปลงใช้ระบุพื้นที่ของงานเท่านั้น การแก้ชื่อหรือเก็บแปลงจะเก็บประวัติไว้เสมอ')} /><PlotManagement ready={ready} notify={setMessage} onBack={() => setPlotRoute(false)} /></AppShell><FeedbackToast visible={Boolean(message)} message={message ?? ''} onDismiss={() => setMessage(null)} /></View>;
  return <View style={styles.root}><AppShell activeTab={tab as BottomTabKey} keyboardAware={tab === 'record' || tab === 'people'} onTabPress={(next) => setTab(next as Tab)} showTabs variant="tabbed" scrollEnabled={tab !== 'work'}>
    <TopBar subtitle={tabTitle[tab]} title={tabTitle[tab]} variant="default" onInfoPress={() => setMessage(helpText[tab])} />{ready.adapter.mode === 'proof' ? <StatusChip label="ข้อมูลทดสอบ V2" variant="offline" /> : null}
    {tab === 'today' ? <TodayScreen {...props} onRecord={() => setTab('record')} onPayment={() => setTab('payment')} onWork={() => setTab('work')} /> : null}
    {tab === 'work' ? <WorkScreen {...props} onRecord={() => setTab('record')} onManagePlots={() => setPlotRoute(true)} /> : null}
    {tab === 'record' ? <RecordScreen {...props} onPayment={() => setTab('payment')} onManagePlots={() => setPlotRoute(true)} /> : null}
    {tab === 'payment' ? <PaymentScreen {...props} preferredPersonId={paymentPersonId} onClearPersonContext={() => setPaymentPersonId(null)} /> : null}
    {tab === 'people' ? <PeopleScreen {...props} onPayment={(personId) => { setPaymentPersonId(personId); setTab('payment'); }} /> : null}
  </AppShell><FeedbackToast visible={visual === 'success-toast' || Boolean(message)} message={visual === 'success-toast' ? 'ข้อมูลทดสอบ: บันทึกสำเร็จแล้ว' : message ?? ''} onDismiss={() => setMessage(null)} /></View>;
}

function TodayScreen({ ready, onRecord, onPayment, onWork }: { ready: Ready; onRecord: () => void; onPayment: () => void; onWork: () => void }) {
  const allTasks = ready.model.tasks.filter((item) => item.workDate === ready.date).sort((a, b) => b.id.localeCompare(a.id)); const allUnpaid = ready.model.obligations.filter((item) => item.remainingSatang > 0); const tasks = allTasks.slice(0, 5); const unpaid = allUnpaid.slice(0, 5);
  return <><FieldCard variant="raised" style={styles.heroCard}><GardenAccent /><View style={styles.heroHeading}><IconDisc icon="today" size={44} tone="gold" /><View style={styles.heroText}><Text style={styles.eyebrow}>ภาพรวมวันนี้</Text><Text style={styles.heroTitle}>งาน {allTasks.length} รายการ</Text><Text style={styles.muted}>งานและเงินค้างจ่ายแยกกันชัดเจน</Text></View></View><PrimaryButton label="+ บันทึกงานวันนี้" onPress={onRecord} /></FieldCard><Summary items={[["งาน", allTasks.length, true], ["ค้างค่าแรง", allUnpaid.reduce((sum, item) => sum + item.remainingSatang, 0), false], ["จ่ายแล้ว", ready.model.obligations.reduce((sum, item) => sum + item.paidSatang, 0), false]]} /><View style={styles.rowHeader}><SectionHeader title="งานที่ทำวันนี้" /><Pressable onPress={onWork}><Text style={styles.route}>ดูงานทั้งหมด</Text></Pressable></View><TaskList tasks={tasks} workers={ready.workers} />{allTasks.length > 5 ? <Text style={styles.caption}>แสดง 5 งานล่าสุดจาก {allTasks.length} งาน</Text> : null}<View style={styles.rowHeader}><SectionHeader title="ค่าแรงค้างจ่าย" /><Pressable onPress={onPayment}><Text style={styles.route}>ดูทั้งหมด</Text></Pressable></View><ObligationList obligations={unpaid} workers={ready.workers} />{allUnpaid.length > 5 ? <Text style={styles.caption}>แสดง 5 รายการล่าสุดจาก {allUnpaid.length} รายการ</Text> : null}<PrimaryButton label="ไปที่จ่ายเงิน" variant="secondary" onPress={onPayment} /></>;
}

function WorkScreen({ ready, refresh, notify, onRecord, onManagePlots }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onRecord: () => void; onManagePlots: () => void }) {
  const { width } = useWindowDimensions(); const calendarCellWidth = Math.floor((width - tokens.spacing.page * 2) / 7); const [month, setMonth] = useState(ready.date.slice(0, 7)); const [selectedDate, setSelectedDate] = useState(ready.date); const [calendar, setCalendar] = useState<Awaited<ReturnType<LaborV2Adapter['getCalendarMonth']>> | null>(null); const [items, setItems] = useState<LaborV2TaskDetail[]>([]); const [cursor, setCursor] = useState<string | null>(null); const [filters, setFilters] = useState<LaborV2WorkListFilters>({}); const [draft, setDraft] = useState<LaborV2WorkListFilters>({}); const [mode, setMode] = useState<'calendar' | 'list' | 'detail'>('calendar'); const [filterVisible, setFilterVisible] = useState(false); const [detail, setDetail] = useState<LaborV2TaskDetail | null>(null);
  const loadMonth = async (next = month) => { const value = await ready.adapter.getCalendarMonth(next); setCalendar(value); const selected = selectedDate.startsWith(next) ? selectedDate : `${next}-01`; setSelectedDate(selected); };
  const loadList = async (nextFilters = filters, nextCursor?: string | null, append = false) => { const result = await ready.adapter.getWorkList(nextFilters, nextCursor ?? undefined, 30); setItems((rows) => append ? [...rows, ...result.items] : result.items); setCursor(result.nextCursor); };
  useEffect(() => { void loadMonth(); }, [month]); useEffect(() => { if (mode === 'list') void loadList(); }, [mode, filters]);
  const previousMonth = () => setMonth((value) => { const date = new Date(`${value}-01T12:00:00`); date.setMonth(date.getMonth() - 1); return date.toISOString().slice(0, 7); }); const nextMonth = () => setMonth((value) => { const date = new Date(`${value}-01T12:00:00`); date.setMonth(date.getMonth() + 1); return date.toISOString().slice(0, 7); });
  const selected = ready.model.tasks.filter((item) => item.workDate === selectedDate); const dayOffset = calendar ? new Date(`${month}-01T12:00:00`).getDay() : 0; const days = calendar?.days ?? []; const openDetail = async (id: string) => { setDetail(await ready.adapter.getTaskDetail(id)); setMode('detail'); };
  if (mode === 'detail' && detail) return <WorkDetailScreen detail={detail} ready={ready} onBack={() => setMode('calendar')} onManagePlots={onManagePlots} />;
  if (mode === 'list') return <View style={styles.listScreen}><View style={styles.rowHeader}><Text style={styles.title}>งานทั้งหมด</Text><Pressable onPress={() => setMode('calendar')}><Text style={styles.route}>ปฏิทิน</Text></Pressable></View><View style={styles.rowHeader}><Text style={styles.caption}>ค้นจากงานที่บันทึก ไม่ปนรายการจ่ายเงิน</Text><Pressable onPress={() => { setDraft(filters); setFilterVisible(true); }}><Text style={styles.route}>ตัวกรอง</Text></Pressable></View><FlatList data={items} keyExtractor={(item) => item.id} contentContainerStyle={styles.flatList} renderItem={({ item }) => <TaskRow item={item} workers={ready.workers} onPress={() => void openDetail(item.id)} />} ListEmptyComponent={<Empty label="ยังไม่มีงานตามตัวกรอง" />} ListFooterComponent={cursor ? <PrimaryButton label="โหลดงานเพิ่ม" variant="secondary" onPress={() => void loadList(filters, cursor, true)} /> : <LegacyReadContext ready={ready} />} /><WorkFilterSheet visible={filterVisible} value={draft} workers={ready.workers} onChange={setDraft} onClose={() => setFilterVisible(false)} onApply={() => { setFilters(draft); setFilterVisible(false); }} /></View>;
  return <View style={styles.listScreen}><FlatList data={selected.slice(0, 5)} keyExtractor={(item) => item.id} contentContainerStyle={styles.flatList} renderItem={({ item }) => <TaskRow item={{ ...item, wageContexts: [] }} workers={ready.workers} onPress={() => void openDetail(item.id)} />} ListHeaderComponent={<><View style={styles.rowHeader}><Text style={styles.title}>ปฏิทินงาน</Text><Pressable onPress={() => setMode('list')}><Text style={styles.route}>รายการงานทั้งหมด</Text></Pressable></View><View style={styles.monthNav}><Pressable onPress={previousMonth}><Text style={styles.monthButton}>‹</Text></Pressable><Text style={styles.monthLabel}>{new Date(`${month}-01T12:00:00`).toLocaleDateString('th-TH', { month: 'long', year: 'numeric' })}</Text><Pressable onPress={nextMonth}><Text style={styles.monthButton}>›</Text></Pressable></View><View style={styles.week}><Text style={styles.weekday}>อา</Text><Text style={styles.weekday}>จ</Text><Text style={styles.weekday}>อ</Text><Text style={styles.weekday}>พ</Text><Text style={styles.weekday}>พฤ</Text><Text style={styles.weekday}>ศ</Text><Text style={styles.weekday}>ส</Text></View><View style={styles.calendar}>{Array.from({ length: dayOffset }).map((_, index) => <View key={`blank-${index}`} style={[styles.dayBlank, { width: calendarCellWidth }]} />)}{days.map((day) => <Pressable key={day.workDate} onPress={() => setSelectedDate(day.workDate)} style={[styles.dayCell, { width: calendarCellWidth }, selectedDate === day.workDate && styles.daySelected]}><Text style={styles.dayNumber}>{Number(day.workDate.slice(-2))}</Text>{day.taskCount ? <Text style={styles.dayCount}>{day.taskCount}</Text> : null}</Pressable>)}</View><View style={styles.rowHeader}><SectionHeader title={`งานวันที่ ${selectedDate}`} /><Pressable onPress={() => { setFilters({ startDate: selectedDate, endDate: selectedDate }); setMode('list'); }}><Text style={styles.route}>ดูทั้งหมด</Text></Pressable></View></>} ListEmptyComponent={<Empty label="ยังไม่มีงานในวันนี้" />} ListFooterComponent={<><>{selected.length > 5 ? <Text style={styles.caption}>แสดง 5 งานล่าสุด · ดูทั้งหมดเพื่อดูครบ</Text> : null}</>{ready.openContracts.length ? <View style={styles.section}><SectionHeader title="งานเหมาที่ยังไม่สรุปยอด" />{ready.openContracts.map((contract) => <OpenContractCard key={contract.id} contract={contract} ready={ready} refresh={refresh} notify={notify} />)}</View> : null}<PrimaryButton label="+ บันทึกงาน" onPress={onRecord} /></>} /></View>;
}

function TaskRow({ item, workers, onPress }: { item: LaborV2TaskDetail; workers: LaborWorker[]; onPress: () => void }) { return <Pressable onPress={onPress}><LedgerListCard><LedgerListRow><IconDisc icon="work" size={36} /><LedgerRowText title={item.title} detail={`${item.workDate} · ${item.assigneePersonIds.map((id) => personName(workers, id)).join(', ')}`} /><LedgerTrailing><Text style={styles.route}>รายละเอียด</Text></LedgerTrailing></LedgerListRow></LedgerListCard></Pressable>; }
function WorkDetailScreen({ detail, ready, onBack, onManagePlots }: { detail: LaborV2TaskDetail; ready: Ready; onBack: () => void; onManagePlots: () => void }) { return <View style={styles.listScreen}><Pressable onPress={onBack}><Text style={styles.route}>‹ กลับไปงาน</Text></Pressable><FieldCard variant="raised" style={styles.detailHero}><IconDisc icon="work" size={44} tone="gold" /><View style={styles.heroText}><Text style={styles.eyebrow}>รายละเอียดงาน</Text><Text style={styles.title}>{detail.title}</Text><Text style={styles.muted}>{detail.workDate} · {detail.assigneePersonIds.map((id) => personName(ready.workers, id)).join(', ')}</Text></View></FieldCard><SectionHeader title="พื้นที่ที่ทำงาน" />{detail.plotTargets.length ? <LedgerListCard>{detail.plotTargets.map((target) => <LedgerListRow key={target.plotId}><IconDisc icon="work" size={32} tone="sage" /><LedgerRowText title={target.currentName} detail={`${target.wasRenamed ? `ชื่อเดิมเมื่อบันทึก: ${target.recordedName}` : 'ชื่อแปลงเมื่อบันทึกยังเหมือนเดิม'}${target.treeLabels.length ? ` · ต้นที่เกี่ยวข้อง: ${target.treeLabels.join(', ')}` : ''}`} /><LedgerTrailing><Text style={styles.route}>อ่านได้</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="งานทั่วไป ไม่ได้ระบุแปลง" />}<PrimaryButton label="จัดการแปลง" variant="secondary" onPress={onManagePlots} /><SectionHeader title="สถานะค่าแรง" />{detail.wageContexts.length ? <LedgerListCard>{detail.wageContexts.map((context) => <LedgerListRow key={`${context.sourceKind}:${context.sourceUnitId}`}><IconDisc icon="payment" size={32} tone={context.state === 'paid' ? 'sage' : 'gold'} /><LedgerRowText title={context.sourceKind === 'contract' ? 'งานเหมา' : context.sourceKind === 'daily' ? 'ค่าแรงรายวัน' : 'ค่าแรงรายชั่วโมง'} detail={context.state === 'open_unpriced' ? 'รอสรุปยอด' : context.state === 'paid' ? 'จ่ายครบแล้ว' : context.state === 'partial' ? 'จ่ายบางส่วน' : 'ค้างจ่าย'} /><LedgerTrailing><StatusChip label={context.state === 'open_unpriced' ? 'รอสรุปยอด' : context.state === 'paid' ? 'จ่ายแล้ว' : context.state === 'partial' ? 'จ่ายบางส่วน' : 'ค้างจ่าย'} variant={context.state === 'paid' ? 'paid' : context.state === 'open_unpriced' ? 'dueSoon' : 'unpaid'} /><Text style={styles.caption}>{context.remainingSatang === null ? '—' : baht(context.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่ผูกค่าแรงกับงานนี้" />}<LegacyReadContext ready={ready} /></View>; }
/** V1 data remains preserved in storage but stays hidden while the V2 product is under active development. */
function LegacyReadContext(_: { ready: Ready }) { return null; }
function WorkFilterSheet({ visible, value, workers, onChange, onClose, onApply }: { visible: boolean; value: LaborV2WorkListFilters; workers: LaborWorker[]; onChange: (value: LaborV2WorkListFilters) => void; onClose: () => void; onApply: () => void }) { const [personPicker, setPersonPicker] = useState(false); const [query, setQuery] = useState(''); const options = workers.filter((worker) => !worker.archivedAt).map((worker) => ({ id: worker.id, label: worker.displayName, meta: worker.specialty })); return <><Modal animationType="slide" presentationStyle="overFullScreen" transparent visible={visible} onRequestClose={onClose}><View style={styles.sheetBackdrop}><View style={styles.filterSheet}><View style={styles.rowHeader}><Text style={styles.title}>ตัวกรองงาน</Text><Pressable onPress={onClose}><Text style={styles.route}>ปิด</Text></Pressable></View><TextInput value={value.startDate ?? ''} onChangeText={(startDate) => onChange({ ...value, startDate: startDate || undefined })} placeholder="ตั้งแต่วันที่ YYYY-MM-DD" style={styles.input} /><TextInput value={value.endDate ?? ''} onChangeText={(endDate) => onChange({ ...value, endDate: endDate || undefined })} placeholder="ถึงวันที่ YYYY-MM-DD" style={styles.input} /><PickerField label="คนทำงาน" value={value.personId ? personName(workers, value.personId) : ''} placeholder="ทั้งหมด" onPress={() => setPersonPicker(true)} />{value.personId ? <Pressable onPress={() => onChange({ ...value, personId: undefined })}><Text style={styles.route}>ล้างคนที่เลือก</Text></Pressable> : null}<View style={styles.segment}>{(['daily', 'hourly', 'contract'] as const).map((kind) => <Pressable key={kind} onPress={() => onChange({ ...value, sourceKind: value.sourceKind === kind ? undefined : kind })} style={[styles.segmentItem, value.sourceKind === kind && styles.segmentActive]}><Text style={value.sourceKind === kind ? styles.activeText : styles.caption}>{kind === 'daily' ? 'รายวัน' : kind === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><View style={styles.segment}>{(['unpaid', 'partial', 'paid', 'open_unpriced'] as const).map((state) => <Pressable key={state} onPress={() => onChange({ ...value, wageState: value.wageState === state ? undefined : state })} style={[styles.segmentItem, value.wageState === state && styles.segmentActive]}><Text style={value.wageState === state ? styles.activeText : styles.caption}>{state === 'unpaid' ? 'ค้าง' : state === 'partial' ? 'บางส่วน' : state === 'paid' ? 'จ่ายแล้ว' : 'รอสรุป'}</Text></Pressable>)}</View><PrimaryButton label="ใช้ตัวกรอง" onPress={onApply} /><PrimaryButton label="ล้างตัวกรอง" variant="secondary" onPress={() => onChange({})} /></View></View></Modal><SearchPickerSheet visible={personPicker} title="เลือกคนทำงาน" query={query} setQuery={setQuery} options={options} recentIds={[]} onPick={(personId) => { onChange({ ...value, personId }); setPersonPicker(false); }} onClose={() => setPersonPicker(false)} emptyLabel="ยังไม่มีคนทำงาน" /></>; }

function OpenContractCard({ contract, ready, refresh, notify }: { contract: LaborV2OpenContractBatch; ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void }) { const [progress, setProgress] = useState(''); const [total, setTotal] = useState(''); const [saving, setSaving] = useState(false); const members = contract.memberPersonIds.map((id) => personName(ready.workers, id)).join(', '); const save = async (kind: 'progress' | 'final') => { const amount = Number(total) * 100; if (kind === 'final' && (!Number.isSafeInteger(amount) || amount <= 0)) return notify('กรอกยอดเหมาสุดท้ายเป็นบาท'); setSaving(true); try { if (kind === 'progress') await ready.adapter.commands.progressContract(contract.id, { progressDate: ready.date, note: progress }); else await ready.adapter.commands.finalizeContract(contract.id, { finalizedAt: ready.date, finalization: { kind: 'lump_total', finalTotalSatang: amount } }); await refresh(); notify(kind === 'progress' ? 'บันทึกความคืบหน้างานเหมาแล้ว' : 'ปิดงานเหมาและสร้างก้อนรับเงินแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'บันทึกงานเหมาไม่สำเร็จ'); } finally { setSaving(false); } }; return <FieldCard><Text style={styles.title}>{contract.title}</Text><Text style={styles.caption}>เริ่ม {contract.startsOn} · {members}</Text><TextInput style={styles.input} value={progress} onChangeText={setProgress} placeholder="บันทึกความคืบหน้า (ไม่บังคับ)" /><PrimaryButton disabled={saving} label="บันทึกความคืบหน้า" variant="secondary" onPress={() => save('progress')} /><MoneyInput label="ยอดเหมาสุดท้าย (บาท)" value={total} onChange={setTotal} /><PrimaryButton disabled={saving} label="ปิดงานเหมาสร้างก้อนรับเงิน" onPress={() => save('final')} /></FieldCard>; }

function RecordScreen({ ready, refresh, notify, onPayment, onManagePlots }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onPayment: () => void; onManagePlots: () => void }) {
  return <LaborRecordGroupEditor ready={ready} refresh={refresh} notify={notify} onPayment={onPayment} onManagePlots={onManagePlots} />;
  /* Retained only as pre-V2-editor source history; this branch is unreachable.
  const scenario = selectLaborWebProofScenario(); const su = 'labor-v2-preview-su'; const phuang = 'labor-v2-preview-phuang'; const [workDate, setWorkDate] = useState(scenario ? '2026-08-21' : ready.date); const [tasks, setTasks] = useState(() => scenario === 'daily-three-task' || scenario === 'open-contract' ? [{ id: 'proof-task-1', title: 'ตัดหญ้า', people: [su] }, { id: 'proof-task-2', title: 'ใส่ปุ๋ย', people: [su] }, { id: 'proof-task-3', title: 'พ่นยา', people: [su] }] : [{ id: 'new-task-1', title: '', people: [] as string[] }]); const [units, setUnits] = useState<Array<{ id: string; kind: Kind; personId: string | null; minutes: string; title: string; members: string[] }>>(() => scenario === 'open-contract' ? [{ id: 'proof-contract', kind: 'contract', personId: null, minutes: '60', title: 'กรอกถุงเพาะชำ', members: [su, phuang] }] : [{ id: 'proof-daily', kind: 'daily', personId: su, minutes: '60', title: '', members: [] }]); const [pick, setPick] = useState<'unit' | 'contract' | number | null>(null); const [unitPick, setUnitPick] = useState<string | null>(null); const [query, setQuery] = useState(''); const [saving, setSaving] = useState(false);
  const activePeople = ready.workers.filter((item) => !item.archivedAt); const options = activePeople.map((item) => ({ id: item.id, label: item.displayName, meta: item.specialty })); const setTask = (index: number, change: Partial<(typeof tasks)[number]>) => setTasks((items) => items.map((task, taskIndex) => taskIndex === index ? { ...task, ...change } : task)); const setUnit = (id: string, change: Partial<(typeof units)[number]>) => setUnits((items) => items.map((item) => item.id === id ? { ...item, ...change } : item));
  const save = async () => { const valid = tasks.filter((item) => item.title.trim() && item.people.length); if (!valid.length || !units.length) return notify('เพิ่ม task และหน่วยค่าตอบแทนก่อนบันทึก'); setSaving(true); try { const taskFacts = valid.map((item) => ({ id: item.id, title: item.title.trim(), assigneePersonIds: item.people })); const daily = units.filter((item) => item.kind === 'daily' && item.personId).map((item) => ({ personId: item.personId!, rateSatang: 35_000, quantityMilli: 1000 as const, taskIds: valid.filter((task) => task.people.includes(item.personId!)).map((task) => task.id) })); const hourly = units.filter((item) => item.kind === 'hourly' && item.personId).flatMap((item) => valid.filter((task) => task.people.includes(item.personId!)).map((task, index) => ({ id: `${item.id}-${index}`, taskId: task.id, personId: item.personId!, rateSatang: 12_000, durationMinutes: Number(item.minutes) || 60 }))); if (daily.some((item) => !item.taskIds.length) || !units.filter((item) => item.kind === 'contract').every((item) => item.title.trim() && item.members.length)) throw new Error('ตรวจคนของแต่ละหน่วยค่าตอบแทนให้ครบ'); await ready.adapter.commands.recordDay({ workDate, tasks: taskFacts, daily, hourly }); for (const unit of units.filter((item) => item.kind === 'contract')) await ready.adapter.commands.startContract({ title: unit.title.trim(), startsOn: workDate, memberPersonIds: unit.members, taskIds: valid.map((item) => item.id) }); await refresh(); notify('บันทึก task และหน่วยค่าตอบแทนแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'บันทึกงานไม่สำเร็จ'); } finally { setSaving(false); } };
  return <><DatePickerField label="วันที่ทำงาน" value={workDate} onChange={setWorkDate} />{scenario === 'daily-three-task' ? <FieldCard variant="raised"><Text style={styles.title}>3 task · พี่สุ · 1 หน่วยรายวัน</Text><Text style={styles.caption}>ตัดหญ้า, ใส่ปุ๋ย, พ่นยา รวมเป็นค่าตอบแทนรายวันครั้งเดียว</Text></FieldCard> : null}{scenario === 'open-contract' ? <FieldCard variant="raised"><Text style={styles.title}>งานเหมา · กรอกถุงเพาะชำ · 2 คน</Text><Text style={styles.caption}>เปิดชุดงานแล้ว · ยังไม่ต้องใส่ราคาและยังไม่มีเงินค้างจ่าย</Text></FieldCard> : null}{scenario ? <View style={styles.section}><SectionHeader title="Task ที่ทำ" /><LedgerListCard>{tasks.map((item) => <LedgerListRow key={item.id}><LedgerRowText title={item.title} detail={item.people.map((id) => personName(activePeople, id)).join(', ')} /><LedgerTrailing><Text style={styles.caption}>task</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard></View> : <TaskListEditor tasks={tasks} workers={activePeople} onAdd={() => setTasks((items) => [...items, { id: `new-task-${Date.now()}`, title: '', people: [] }])} onChange={setTask} onPick={(index) => setPick(index)} onRemove={(index) => setTasks((items) => items.length === 1 ? items : items.filter((_item, taskIndex) => taskIndex !== index))} />}<View style={styles.section}><SectionHeader title="หน่วยค่าตอบแทน" />{units.map((unit) => <FieldCard key={unit.id}><View style={styles.rowHeader}><Text style={styles.title}>{unit.kind === 'daily' ? 'รายวัน · รวมอัตโนมัติ' : unit.kind === 'hourly' ? 'รายชั่วโมง · คนและกะ' : 'งานเหมา · เปิดชุดงาน'}</Text><Pressable onPress={() => setUnits((items) => items.filter((item) => item.id !== unit.id))}><Text style={styles.remove}>ลบ</Text></Pressable></View>{unit.kind === 'contract' ? <><TextInput style={styles.input} value={unit.title} onChangeText={(title) => setUnit(unit.id, { title })} placeholder="ชื่อชุดงาน" /><PickerField label="สมาชิกชุดงาน" value={`${unit.members.length} คน`} placeholder="เลือกสมาชิก" onPress={() => { setUnitPick(unit.id); setPick('contract'); }} /><Text style={styles.caption}>ยังไม่ต้องใส่ราคา · เปิดไว้ก่อนได้</Text></> : <><PickerField label="คนทำงาน" value={personName(activePeople, unit.personId)} placeholder="เลือกคน" onPress={() => { setUnitPick(unit.id); setPick('unit'); }} />{unit.kind === 'hourly' ? <MoneyInput label="นาทีในกะ" value={unit.minutes} onChange={(minutes) => setUnit(unit.id, { minutes })} /> : <Text style={styles.caption}>หลาย task ของคนเดียวกันรวมเป็น 1 หน่วยรายวัน</Text>}</>}</FieldCard>)}</View><View style={styles.segment}>{(['daily', 'hourly', 'contract'] as Kind[]).map((kind) => <Pressable key={kind} onPress={() => setUnits((items) => [...items, { id: `unit-${Date.now()}-${kind}`, kind, personId: null, minutes: '60', title: '', members: [] }])} style={styles.segmentItem}><Text style={styles.caption}>+ {kind === 'daily' ? 'รายวัน' : kind === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><FormFeedback kind="notice">เพิ่มได้หลายหน่วยในวันเดียว: รายวันของคนหนึ่ง และงานเหมาแบบยังไม่รู้ราคาอยู่ร่วมกันได้</FormFeedback><PrimaryButton disabled={saving} label={saving ? 'กำลังบันทึก…' : 'บันทึกงาน'} onPress={save} /><PrimaryButton label="ไปจ่ายจากก้อนค่าตอบแทน" variant="secondary" onPress={onPayment} />
  <MultiSearchPickerSheet visible={typeof pick === 'number'} title="คนทำงานใน task" query={query} setQuery={setQuery} options={options} selectedIds={typeof pick === 'number' ? tasks[pick]?.people ?? [] : []} onToggle={(id) => { if (typeof pick !== 'number') return; const selected = tasks[pick]?.people ?? []; setTask(pick, { people: selected.includes(id) ? selected.filter((item) => item !== id) : [...selected, id] }); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" />
  <SearchPickerSheet visible={pick === 'unit'} title="เลือกคนของหน่วยค่าตอบแทน" query={query} setQuery={setQuery} options={options} recentIds={[]} onPick={(id) => { if (unitPick) setUnit(unitPick, { personId: id }); setPick(null); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" />
  <MultiSearchPickerSheet visible={pick === 'contract'} title="สมาชิกชุดงานเหมา" query={query} setQuery={setQuery} options={options} selectedIds={units.find((item) => item.id === (unitPick ?? ''))?.members ?? []} onToggle={(id) => { if (!unitPick) return; const members = units.find((item) => item.id === unitPick)?.members ?? []; setUnit(unitPick, { members: members.includes(id) ? members.filter((item) => item !== id) : [...members, id] }); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" /></>;
  */
}

type PaymentRowDraft = { wage?: string; bonus?: string; advanceId?: string | null; recovery?: string };

function PaymentScreen({ ready, refresh, notify, preferredPersonId, onClearPersonContext }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; preferredPersonId?: string | null; onClearPersonContext: () => void }) {
  const proofPayment = selectLaborWebProofScenario() === 'payment-selection';
  const [selectedIds, setSelectedIds] = useState<string[]>(() => proofPayment ? ready.model.obligations.filter((item) => item.remainingSatang > 0).slice(0, 4).map((item) => item.id) : []);
  const [draft, setDraft] = useState<Awaited<ReturnType<LaborV2Adapter['getPaymentBatchDraft']>> | null>(null);
  const [picker, setPicker] = useState(proofPayment); const [query, setQuery] = useState(''); const [advancePickerFor, setAdvancePickerFor] = useState<string | null>(null);
  const [rows, setRows] = useState<Record<string, PaymentRowDraft>>({}); const [paymentDate, setPaymentDate] = useState(ready.date); const [method, setMethod] = useState('เงินสด'); const [note, setNote] = useState(''); const [confirm, setConfirm] = useState(false); const [saving, setSaving] = useState(false);
  const outstanding = ready.model.obligations.filter((item) => item.remainingSatang > 0);
  useEffect(() => { let alive = true; void ready.adapter.getPaymentBatchDraft({ personId: preferredPersonId ?? undefined, selectedObligationIds: selectedIds }).then((next) => alive && setDraft(next)).catch(() => alive && notify('เปิดรายการค่าแรงค้างจ่ายไม่สำเร็จ')); return () => { alive = false; }; }, [ready.adapter, preferredPersonId, selectedIds]);
  const selected = draft?.selected ?? [];
  const rowDraft = (item: typeof selected[number]) => rows[item.obligationId] ?? {};
  const wageSatang = (item: typeof selected[number]) => Math.round(Number(rowDraft(item).wage ?? item.remainingSatang / 100) * 100);
  const bonusSatang = (item: typeof selected[number]) => Math.round(Number(rowDraft(item).bonus ?? 0) * 100);
  const recoverySatang = (item: typeof selected[number]) => item.recipientKind === 'person' ? Math.round(Number(rowDraft(item).recovery ?? 0) * 100) : 0;
  const cashTotal = selected.reduce((total, item) => total + wageSatang(item) + bonusSatang(item) - recoverySatang(item), 0);
  const setRow = (id: string, next: Partial<PaymentRowDraft>) => setRows((current) => ({ ...current, [id]: { ...current[id], ...next } }));
  const options = (draft?.available ?? []).map((item) => ({ id: item.obligationId, label: `${item.title} · ${baht(item.remainingSatang)}`, meta: item.recipientKind === 'group' ? `ชุดรับเงิน · ${item.effectiveDate}` : `${personName(ready.workers, item.personId)} · ${item.effectiveDate}` }));
  const toggle = (id: string) => setSelectedIds((items) => items.includes(id) ? items.filter((item) => item !== id) : [...items, id]);
  const advancesFor = (item: typeof selected[number]) => item.recipientKind === 'person' ? ready.advances.filter((advance) => advance.personId === item.personId && advance.remainingSatang > 0) : [];
  const post = async () => { if (!selected.length) return; const missingAdvance = selected.find((item) => item.recipientKind === 'person' && recoverySatang(item) > 0 && !rowDraft(item).advanceId); if (missingAdvance) return notify(`เลือกเงินเบิกของ ${personName(ready.workers, missingAdvance.personId)} ก่อนหักเงิน`); setSaving(true); try {
    await ready.adapter.commands.postPayment({ paymentDate, method: method.trim() || 'cash', note: note.trim() || undefined, settlements: selected.map((item) => {
      const row = rowDraft(item); const recovery = recoverySatang(item);
      return { obligationId: item.obligationId, wageSatang: wageSatang(item), bonusSatang: bonusSatang(item), advanceRecoveries: item.recipientKind === 'person' && recovery > 0 && row.advanceId ? [{ advanceId: row.advanceId, amountSatang: recovery }] : [] };
    }) });
    await refresh(); setSelectedIds([]); setRows({}); setNote(''); notify('บันทึกการจ่ายเงินแล้ว');
  } catch (error) { notify(error instanceof Error ? error.message : 'จ่ายเงินไม่สำเร็จ'); } finally { setConfirm(false); setSaving(false); } };
  const selectedTotal = selected.reduce((total, item) => total + item.remainingSatang, 0);
  const advancePickerItem = selected.find((item) => item.obligationId === advancePickerFor);
  return <><FieldCard variant="raised" style={styles.heroCard}><GardenAccent /><View style={styles.heroHeading}><IconDisc icon="payment" size={44} tone="gold" /><View style={styles.heroText}><Text style={styles.eyebrow}>สมุดจ่ายเงิน</Text><Text style={styles.heroTitle}>ค้างค่าแรง {baht(outstanding.reduce((sum, item) => sum + item.remainingSatang, 0))}</Text><Text style={styles.muted}>{preferredPersonId ? `เลือกเฉพาะค่าแรงของ ${personName(ready.workers, preferredPersonId)}` : 'รวมหลายก้อนจ่ายเป็นครั้งเดียวได้'}</Text>{preferredPersonId ? <Pressable onPress={onClearPersonContext}><Text style={styles.route}>ดูค่าแรงค้างจ่ายทั้งหมด</Text></Pressable> : null}</View></View></FieldCard><AmountSummary items={[{ label: 'ก้อนค้างจ่าย', value: `${outstanding.length} รายการ`, icon: 'payment' }, { label: 'เลือกแล้ว', value: `${selected.length} รายการ`, icon: 'today' }]} /><PickerField label="เลือกค่าแรงค้างจ่าย" value={selected.length ? `${selected.length} รายการ · ${baht(selectedTotal)}` : null} placeholder="เลือกค่าแรงที่จะจ่าย" onPress={() => setPicker(true)} />{selected.length ? <View style={styles.section}><SectionHeader title="ตรวจรายการที่เลือก" />{selected.map((item) => <PaymentSettlementRow key={item.obligationId} advances={advancesFor(item)} item={item} workers={ready.workers} onChange={(next) => setRow(item.obligationId, next)} onPickAdvance={() => setAdvancePickerFor(item.obligationId)} value={rowDraft(item)} wage={wageSatang(item)} bonus={bonusSatang(item)} recovery={recoverySatang(item)} />)}<FieldCard variant="summary"><Text style={styles.eyebrow}>สรุปการจ่ายครั้งนี้</Text><Text style={styles.title}>เงินสดที่จ่าย {baht(cashTotal)}</Text><Text style={styles.caption}>ค่าแรงและเงินเพิ่ม หักเฉพาะเงินเบิกของคนทำงานคนเดียวกัน</Text></FieldCard><DatePickerField label="วันที่จ่าย" value={paymentDate} onChange={setPaymentDate} /><TextInput style={styles.input} value={method} onChangeText={setMethod} placeholder="วิธีจ่าย เช่น เงินสด" /><TextInput style={styles.input} value={note} onChangeText={setNote} placeholder="หมายเหตุ (ไม่บังคับ)" /><PrimaryButton disabled={saving} label="ตรวจแล้ว ยืนยันจ่ายเงิน" onPress={() => setConfirm(true)} /></View> : <Empty label="เลือกค่าแรงค้างจ่ายได้หลายรายการ แล้วค่อยตรวจยอดก่อนจ่าย" />}<MultiSearchPickerSheet visible={picker} title="เลือกค่าแรงค้างจ่าย" query={query} setQuery={setQuery} options={options} selectedIds={selectedIds} selectionLabel="รายการ" onToggle={toggle} onClose={() => setPicker(false)} emptyLabel="ไม่มีรายการค้างจ่ายในตอนนี้" />{advancePickerFor && advancePickerItem ? <SearchPickerSheet visible title="เลือกเงินเบิกของคนนี้" query={query} setQuery={setQuery} options={advancesFor(advancePickerItem).map((item) => ({ id: item.id, label: `${baht(item.remainingSatang)} · ${item.advanceDate}`, meta: item.note || 'เงินเบิกคงเหลือ' }))} recentIds={[]} onPick={(advanceId) => { setRow(advancePickerFor, { advanceId }); setAdvancePickerFor(null); }} onClose={() => setAdvancePickerFor(null)} emptyLabel="ไม่มีเงินเบิกคงเหลือ" /> : null}<ConfirmActionSheet visible={confirm} title="ยืนยันการจ่ายเงิน" detail={`จ่าย ${selected.length} รายการ · เงินสดที่จ่าย ${baht(cashTotal)}`} cancelLabel="กลับไปตรวจ" confirmLabel="ยืนยันจ่าย" onCancel={() => setConfirm(false)} onConfirm={post} /></>;
}

function PaymentSettlementRow({ advances, bonus, item, onChange, onPickAdvance, recovery, value, wage, workers }: { advances: LaborWorkerAdvance[]; item: NonNullable<Awaited<ReturnType<LaborV2Adapter['getPaymentBatchDraft']>>>['selected'][number]; value: PaymentRowDraft; wage: number; bonus: number; recovery: number; workers: LaborWorker[]; onChange: (value: Partial<PaymentRowDraft>) => void; onPickAdvance: () => void }) {
  const advanceOptions = advances.map((advance) => ({ id: advance.id, label: `${baht(advance.remainingSatang)} · ${advance.advanceDate}` }));
  return <FieldCard style={styles.paymentRow}><View style={styles.rowHeader}><View style={styles.heroText}><Text style={styles.eyebrow}>{item.recipientKind === 'group' ? 'ชุดรับเงิน' : personName(workers, item.personId)}</Text><Text style={styles.title}>{item.title}</Text><Text style={styles.caption}>{item.effectiveDate} · ค้าง {baht(item.remainingSatang)}</Text></View><Pressable onPress={() => onChange({ wage: undefined, bonus: undefined, recovery: undefined, advanceId: null })}><Text style={styles.route}>เต็มจำนวน</Text></Pressable></View><MoneyInput label="จ่ายค่าแรง (บาท)" value={value.wage ?? String(item.remainingSatang / 100)} onChange={(wageValue) => onChange({ wage: wageValue })} /><MoneyInput label="เงินเพิ่ม (บาท)" value={value.bonus ?? '0'} onChange={(bonusValue) => onChange({ bonus: bonusValue })} />{item.recipientKind === 'person' ? <><MoneyInput label="หักเงินเบิก (บาท)" value={value.recovery ?? '0'} onChange={(recoveryValue) => onChange({ recovery: recoveryValue })} /><PickerField label="เลือกเงินเบิกของคนนี้" value={advanceOptions.find((option) => option.id === value.advanceId)?.label} placeholder="เลือกเงินเบิก (ถ้ามี)" onPress={onPickAdvance} /></> : <FormFeedback kind="notice">ชุดรับเงินจ่ายเป็นก้อนเดียว จึงไม่มีการหักเงินเบิก</FormFeedback>}<Text style={styles.caption}>เงินสดของรายการนี้ {baht(wage + bonus - recovery)}</Text></FieldCard>;
}

function PeopleScreen({ ready, refresh, notify, onPayment }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onPayment: (personId: string) => void }) {
  const [adding, setAdding] = useState(false); const [name, setName] = useState(''); const [specialty, setSpecialty] = useState(''); const [query, setQuery] = useState(''); const [showArchived, setShowArchived] = useState(false); const [personId, setPersonId] = useState<string | null>(null);
  const create = async () => { if (!name.trim()) return notify('กรอกชื่อคนทำงาน'); try { await ready.adapter.workers.create({ displayName: name.trim(), specialty: specialty.trim() }); await refresh(); setName(''); setSpecialty(''); setAdding(false); notify('เพิ่มคนทำงานแล้ว'); } catch { notify('เพิ่มคนทำงานไม่สำเร็จ'); } };
  if (personId) return <PersonDetailScreen ready={ready} refresh={refresh} notify={notify} personId={personId} onBack={() => setPersonId(null)} onPayment={onPayment} />;
  const matches = (worker: LaborWorker) => `${worker.displayName} ${worker.specialty} ${worker.phone}`.toLowerCase().includes(query.trim().toLowerCase()); const active = ready.workers.filter((item) => !item.archivedAt && matches(item)); const archived = ready.workers.filter((item) => item.archivedAt && matches(item));
  return <><FieldCard variant="raised" style={styles.heroCard}><GardenAccent /><View style={styles.heroHeading}><IconDisc icon="people" size={44} tone="sage" /><View style={styles.heroText}><Text style={styles.eyebrow}>รายชื่อคนทำงาน</Text><Text style={styles.heroTitle}>กำลังใช้งาน {active.length} คน</Text><Text style={styles.muted}>รายชื่อที่เก็บไว้ดูประวัติได้ แต่เลือกบันทึกงานใหม่ไม่ได้</Text></View></View></FieldCard><TextInput style={styles.input} value={query} onChangeText={setQuery} placeholder="ค้นหาชื่อ งานที่ถนัด หรือเบอร์โทร" /><SectionHeader title={`กำลังใช้งาน (${active.length})`} /><LedgerListCard>{active.map((item) => <Pressable key={item.id} onPress={() => setPersonId(item.id)}><LedgerListRow><IconDisc icon="people" size={36} /><LedgerRowText title={item.displayName} detail={item.specialty || 'ยังไม่ได้ระบุงานที่ถนัด'} /><LedgerTrailing><Text style={styles.route}>ดูข้อมูล</Text></LedgerTrailing></LedgerListRow></Pressable>)}</LedgerListCard>{!active.length ? <Empty label="ไม่พบคนทำงาน" /> : null}<Pressable onPress={() => setShowArchived((value) => !value)}><Text style={styles.route}>{showArchived ? 'ซ่อนรายชื่อที่เก็บไว้' : `ดูรายชื่อที่เก็บไว้ (${archived.length})`}</Text></Pressable>{showArchived ? <><SectionHeader title="รายชื่อที่เก็บไว้" /><LedgerListCard>{archived.map((item) => <Pressable key={item.id} onPress={() => setPersonId(item.id)}><LedgerListRow><IconDisc icon="people" size={36} tone="gold" /><LedgerRowText title={item.displayName} detail={item.specialty || 'ประวัติคนทำงาน'} /><LedgerTrailing><StatusChip label="เก็บไว้" variant="archived" /></LedgerTrailing></LedgerListRow></Pressable>)}</LedgerListCard></> : null}<PrimaryButton label={adding ? 'ยกเลิก' : '+ เพิ่มคนทำงาน'} onPress={() => setAdding((value) => !value)} />{adding ? <FieldCard><TextInput style={styles.input} value={name} onChangeText={setName} placeholder="ชื่อคนทำงาน" /><TextInput style={styles.input} value={specialty} onChangeText={setSpecialty} placeholder="งานที่ถนัด (ไม่บังคับ)" /><PrimaryButton label="บันทึกคนทำงาน" onPress={create} /></FieldCard> : null}</>;
}

function PersonDetailScreen({ ready, refresh, notify, personId, onBack, onPayment }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; personId: string; onBack: () => void; onPayment: (personId: string) => void }) {
  const person = ready.workers.find((item) => item.id === personId); const [detail, setDetail] = useState<LaborV2PersonDetail | null>(null); const [editing, setEditing] = useState(false); const [archiveConfirm, setArchiveConfirm] = useState(false); const [advanceSheet, setAdvanceSheet] = useState(false); const [advanceConfirm, setAdvanceConfirm] = useState(false); const [advanceDate, setAdvanceDate] = useState(ready.date); const [advanceAmount, setAdvanceAmount] = useState(''); const [advanceMethod, setAdvanceMethod] = useState('เงินสด'); const [advanceNote, setAdvanceNote] = useState(''); const [displayName, setDisplayName] = useState(person?.displayName ?? ''); const [specialty, setSpecialty] = useState(person?.specialty ?? ''); const [phone, setPhone] = useState(person?.phone ?? ''); const [note, setNote] = useState(person?.note ?? ''); const [reason, setReason] = useState(''); const [saving, setSaving] = useState(false);
  useEffect(() => { void ready.adapter.getPersonDetail(personId).then(setDetail).catch(() => notify('เปิดข้อมูลคนทำงานไม่สำเร็จ')); }, [ready.adapter, ready.model, personId]);
  if (!person) return <Empty label="ไม่พบคนทำงาน" />;
  const workDates = [...new Set(detail?.tasks.map((task) => task.workDate) ?? [])].sort().reverse(); const unpaid = detail?.obligations.filter((item) => item.remainingSatang > 0).reduce((sum, item) => sum + item.remainingSatang, 0) ?? 0; const advanceRemaining = detail?.advances.reduce((sum, item) => sum + item.remainingSatang, 0) ?? 0;
  const save = async () => { if (!reason.trim()) return notify('บอกเหตุผลที่แก้ไขก่อนบันทึก'); setSaving(true); try { await ready.adapter.workers.update(personId, { displayName, specialty, phone, note, reason }); await refresh(); setReason(''); setEditing(false); notify('บันทึกการแก้ไขพร้อมประวัติแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'แก้ไขข้อมูลไม่สำเร็จ'); } finally { setSaving(false); } };
  const archive = async () => { if (!reason.trim()) return notify('บอกเหตุผลที่เก็บรายชื่อก่อน'); setSaving(true); try { await ready.adapter.workers.archive(personId, reason); await refresh(); notify('เก็บรายชื่อไว้แล้ว ประวัติเดิมยังดูได้'); onBack(); } catch (error) { notify(error instanceof Error ? error.message : 'เก็บรายชื่อไม่สำเร็จ'); } finally { setSaving(false); setArchiveConfirm(false); } };
  const issueAdvance = async () => { const amountSatang = Math.round(Number(advanceAmount) * 100); if (amountSatang <= 0) return notify('กรอกจำนวนเงินเบิกเป็นบาท'); setSaving(true); try { await ready.adapter.personFinance.issueAdvance({ personId, advanceDate, amountSatang, method: advanceMethod.trim() || 'cash', note: advanceNote.trim() || undefined }); await refresh(); setAdvanceAmount(''); setAdvanceNote(''); notify('บันทึกเงินเบิกแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'บันทึกเงินเบิกไม่สำเร็จ'); } finally { setSaving(false); setAdvanceConfirm(false); } };
  return <View style={styles.listScreen}><Pressable onPress={onBack}><Text style={styles.route}>‹ กลับไปรายชื่อ</Text></Pressable><FieldCard variant="raised" style={styles.detailHero}><IconDisc icon="people" size={48} tone={person.archivedAt ? 'gold' : 'sage'} /><View style={styles.heroText}><Text style={styles.eyebrow}>{person.archivedAt ? 'รายชื่อที่เก็บไว้' : 'คนทำงาน'}</Text><Text style={styles.title}>{person.displayName}</Text><Text style={styles.muted}>{person.specialty || 'ยังไม่ได้ระบุงานที่ถนัด'}{person.phone ? ` · ${person.phone}` : ''}</Text>{person.note ? <Text style={styles.caption}>{person.note}</Text> : null}</View></FieldCard><Summary items={[["ค่าแรงค้างจ่าย", unpaid, false], ["เงินเบิกคงเหลือ", advanceRemaining, false], ["งานที่บันทึก", detail?.tasks.length ?? 0, true]]} />{!person.archivedAt ? <><PrimaryButton label="ไปจ่ายเงินให้คนนี้" onPress={() => onPayment(personId)} /><PrimaryButton label="ให้เงินเบิก" variant="secondary" onPress={() => setAdvanceSheet(true)} /><PrimaryButton label={editing ? 'ยกเลิกแก้ไข' : 'แก้ไขข้อมูล'} variant="secondary" onPress={() => { setEditing((value) => !value); setReason(''); }} /></> : <FieldCard variant="summary"><Text style={styles.caption}>รายชื่อนี้เก็บไว้แล้ว จึงเลือกบันทึกงานใหม่ไม่ได้ แต่ประวัติยังอยู่ครบ</Text></FieldCard>}{editing ? <FieldCard><SectionHeader title="แก้ไขข้อมูลคนทำงาน" /><TextInput style={styles.input} value={displayName} onChangeText={setDisplayName} placeholder="ชื่อคนทำงาน" /><TextInput style={styles.input} value={specialty} onChangeText={setSpecialty} placeholder="งานที่ถนัด" /><TextInput style={styles.input} value={phone} onChangeText={setPhone} placeholder="เบอร์โทร" keyboardType="phone-pad" /><TextInput style={styles.input} value={note} onChangeText={setNote} placeholder="หมายเหตุ" /><TextInput style={styles.input} value={reason} onChangeText={setReason} placeholder="เหตุผลที่แก้ไข (จำเป็น)" /><PrimaryButton disabled={saving} label="บันทึกการแก้ไข" onPress={save} /></FieldCard> : null}<SectionHeader title="ปฏิทินและงานที่ทำ" />{workDates.length ? <LedgerListCard>{workDates.map((workDate) => <LedgerListRow key={workDate}><IconDisc icon="work" size={32} /><LedgerRowText title={workDate} detail={(detail?.tasks.filter((task) => task.workDate === workDate).map((task) => task.title) ?? []).join(', ')} /><LedgerTrailing><Text style={styles.caption}>{detail?.tasks.filter((task) => task.workDate === workDate).length} งาน</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีงาน V2 ของคนนี้" />}<SectionHeader title="การจ่ายเงินของคนนี้" />{detail?.payments.length ? <LedgerListCard>{detail.payments.map((payment) => <LedgerListRow key={payment.id}><IconDisc icon="payment" size={32} /><LedgerRowText title={`จ่ายวันที่ ${payment.paymentDate}`} detail="ประวัติการจ่ายค่าแรงของคนนี้" /><LedgerTrailing><Text style={styles.caption}>{baht(payment.cashPaidSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีประวัติการจ่ายเงิน V2" />}<SectionHeader title="เงินเบิก" />{detail?.advances.length ? <LedgerListCard>{detail.advances.map((advance) => <LedgerListRow key={advance.id}><IconDisc icon="payment" size={32} tone="gold" /><LedgerRowText title={advance.advanceDate} detail={advance.note || 'เงินเบิก'} /><LedgerTrailing><Text style={styles.caption}>เหลือ {baht(advance.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ไม่มีเงินเบิก" />}<LegacyReadContext ready={ready} />{!person.archivedAt ? <><TextInput style={styles.input} value={reason} onChangeText={setReason} placeholder="เหตุผลที่เก็บรายชื่อ (จำเป็น)" /><PrimaryButton label="เก็บรายชื่อคนนี้" variant="secondary" onPress={() => setArchiveConfirm(true)} /><ConfirmActionSheet visible={archiveConfirm} title="เก็บรายชื่อคนทำงาน" detail="จะยังเก็บประวัติงานและการเงินไว้ดูได้ แต่ใช้เลือกงานใหม่ไม่ได้" cancelLabel="กลับไปตรวจ" confirmLabel="ยืนยันเก็บรายชื่อ" onCancel={() => setArchiveConfirm(false)} onConfirm={archive} /><AdvanceIssueSheet visible={advanceSheet} date={advanceDate} amount={advanceAmount} method={advanceMethod} note={advanceNote} onClose={() => setAdvanceSheet(false)} onChangeDate={setAdvanceDate} onChangeAmount={setAdvanceAmount} onChangeMethod={setAdvanceMethod} onChangeNote={setAdvanceNote} onSubmit={() => { if (Number(advanceAmount) > 0) { setAdvanceSheet(false); setAdvanceConfirm(true); } else notify('กรอกจำนวนเงินเบิกเป็นบาท'); }} /><ConfirmActionSheet visible={advanceConfirm} title="ยืนยันให้เงินเบิก" detail={`ให้เงินเบิก ${baht(Math.round(Number(advanceAmount) * 100))} แก่ ${person.displayName} วันที่ ${advanceDate}`} cancelLabel="กลับไปแก้ไข" confirmLabel="ยืนยันให้เงินเบิก" onCancel={() => { setAdvanceConfirm(false); setAdvanceSheet(true); }} onConfirm={issueAdvance} confirmDisabled={saving} /></> : null}</View>;
}

function AdvanceIssueSheet({ amount, date, method, note, onChangeAmount, onChangeDate, onChangeMethod, onChangeNote, onClose, onSubmit, visible }: { visible: boolean; date: string; amount: string; method: string; note: string; onChangeDate: (value: string) => void; onChangeAmount: (value: string) => void; onChangeMethod: (value: string) => void; onChangeNote: (value: string) => void; onClose: () => void; onSubmit: () => void }) {
  return <Modal animationType="slide" onRequestClose={onClose} presentationStyle="overFullScreen" transparent visible={visible}><View style={styles.sheetBackdrop}><View style={styles.advanceSheet}><Text style={styles.title}>ให้เงินเบิก</Text><Text style={styles.muted}>บันทึกเงินเบิกแยกจากค่าแรง จึงให้ได้แม้ยังไม่มีงาน</Text><DatePickerField label="วันที่ให้เงินเบิก" value={date} onChange={onChangeDate} /><MoneyInput label="จำนวนเงินเบิก (บาท)" value={amount} onChange={onChangeAmount} /><TextInput style={styles.input} value={method} onChangeText={onChangeMethod} placeholder="วิธีให้เงิน เช่น เงินสด (ไม่บังคับ)" /><TextInput style={styles.input} value={note} onChangeText={onChangeNote} placeholder="หมายเหตุ (ไม่บังคับ)" /><PrimaryButton label="ตรวจแล้ว บันทึกเงินเบิก" onPress={onSubmit} /><PrimaryButton label="ยกเลิก" variant="secondary" onPress={onClose} /></View></View></Modal>;
}

function TaskListEditor({ tasks, workers, onAdd, onChange, onPick, onRemove }: { tasks: Array<{ id: string; title: string; people: string[] }>; workers: LaborWorker[]; onAdd: () => void; onChange: (index: number, value: Partial<{ id: string; title: string; people: string[] }>) => void; onPick: (index: number) => void; onRemove: (index: number) => void }) { return <View style={styles.section}><SectionHeader title="Task ที่ทำ" />{tasks.map((item, index) => <FieldCard key={item.id}><TextInput style={styles.input} value={item.title} onChangeText={(title) => onChange(index, { title })} placeholder={`งานที่ ${index + 1}`} /><PickerField label="คนทำงาน" value={item.people.map((id) => personName(workers, id)).join(', ')} placeholder="เลือกคนใน task" onPress={() => onPick(index)} /><Pressable onPress={() => onRemove(index)}><Text style={styles.remove}>ลบ task นี้</Text></Pressable></FieldCard>)}<PrimaryButton label="+ เพิ่ม task" variant="secondary" onPress={onAdd} /></View>; }
function CompensationUnitCard({ kind, onKind, unitName, minutes, contractTitle, contractCount, onUnit, onMinutes, onContractTitle, onContract }: { kind: Kind; onKind: (value: Kind) => void; unitName: string; minutes: string; contractTitle: string; contractCount: number; onUnit: () => void; onMinutes: (value: string) => void; onContractTitle: (value: string) => void; onContract: () => void }) { return <View style={styles.section}><SectionHeader title="หน่วยค่าตอบแทน" /><View style={styles.segment}>{(['daily', 'hourly', 'contract'] as Kind[]).map((item) => <Pressable key={item} onPress={() => onKind(item)} style={[styles.segmentItem, kind === item && styles.segmentActive]}><Text style={kind === item ? styles.activeText : styles.caption}>{item === 'daily' ? 'รายวัน' : item === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><FieldCard>{kind === 'daily' ? <><Text style={styles.title}>รายวัน · รวมอัตโนมัติ</Text><PickerField label="คนทำงาน" value={unitName} placeholder="เลือกคน" onPress={onUnit} /><Text style={styles.caption}>หนึ่งคนหนึ่งวันได้ไม่เกินเต็มวัน</Text></> : null}{kind === 'hourly' ? <><Text style={styles.title}>รายชั่วโมง · คนและกะ</Text><PickerField label="คนทำงาน" value={unitName} placeholder="เลือกคน" onPress={onUnit} /><MoneyInput label="นาทีในกะ" value={minutes} onChange={onMinutes} /><Text style={styles.caption}>อัตราเดียวกันรวมกันเฉพาะในคำสั่งนี้</Text></> : null}{kind === 'contract' ? <><Text style={styles.title}>งานเหมา · เปิดชุดงานก่อนได้</Text><TextInput style={styles.input} value={contractTitle} onChangeText={onContractTitle} placeholder="ชื่อชุดงาน" /><PickerField label="สมาชิกชุดงาน" value={`${contractCount} คน`} placeholder="เลือกสมาชิก" onPress={onContract} /><Text style={styles.caption}>ไม่ต้องใส่ราคา/จำนวนตอนเปิดงาน</Text></> : null}</FieldCard></View>; }
function TaskList({ tasks, workers }: { tasks: LaborV2ReadModel['tasks']; workers: LaborWorker[] }) { return tasks.length ? <LedgerListCard>{tasks.map((item) => <LedgerListRow key={item.id}><IconDisc icon="work" size={34} /><LedgerRowText title={item.title} detail={item.assigneePersonIds.map((id) => personName(workers, id)).join(', ')} /><LedgerTrailing><Text style={styles.caption}>งาน</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีงาน" />; }
function ObligationList({ obligations, workers }: { obligations: LaborV2ReadModel['obligations']; workers: LaborWorker[] }) { return obligations.length ? <LedgerListCard>{obligations.map((item) => <LedgerListRow key={item.id}><IconDisc icon="payment" size={34} tone={item.recipientKind === 'group' ? 'gold' : 'sage'} /><LedgerRowText title={item.sourceKind === 'contract' ? 'ชุดงานเหมา' : item.sourceKind === 'daily' ? 'รายวัน' : 'รายชั่วโมง'} detail={item.recipientKind === 'group' ? 'ชุดรับเงิน · ก้อนเดียวของชุดงาน' : personName(workers, item.personId)} /><LedgerTrailing><StatusChip label="ค้างจ่าย" variant="unpaid" /><Text style={styles.caption}>{baht(item.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ไม่มีค่าตอบแทนค้างจ่าย" />; }
function Summary({ items }: { items: Array<[string, number, boolean]> }) { return <AmountSummary items={items.map(([label, value, count]) => ({ label, value: count ? String(value) : baht(value), icon: label.includes('งาน') ? 'work' : label.includes('เบิก') ? 'payment' : 'today' }))} />; }
function MoneyInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput style={styles.input} keyboardType="number-pad" value={value} onChangeText={onChange} /></View>; }
function Empty({ label }: { label: string }) { return <FieldCard><Text style={styles.muted}>{label}</Text></FieldCard>; }
const styles = StyleSheet.create({ root: { backgroundColor: tokens.color.surface.sand, flex: 1 }, heroCard: { gap: 14, overflow: 'hidden', padding: tokens.spacing.card, position: 'relative' }, heroHeading: { alignItems: 'flex-start', flexDirection: 'row', gap: 12 }, heroText: { flex: 1, gap: 3, minWidth: 0 }, heroTitle: { color: tokens.color.text.primary, fontSize: 28, fontWeight: '800', lineHeight: 36 }, detailHero: { alignItems: 'flex-start', flexDirection: 'row', gap: 12 }, moneyCard: { backgroundColor: tokens.color.surface.sage, gap: 8 }, paymentRow: { gap: 12 }, advanceSheet: { backgroundColor: tokens.color.surface.sand, borderTopLeftRadius: tokens.radius.hero, borderTopRightRadius: tokens.radius.hero, gap: 12, padding: tokens.spacing.card }, title: { color: tokens.color.text.primary, fontSize: tokens.typography.h2.size, fontWeight: '800' }, eyebrow: { color: tokens.color.text.muted, fontSize: tokens.typography.metadata.size, fontWeight: '700' }, muted: { color: tokens.color.text.muted, fontSize: tokens.typography.body.size, lineHeight: 23 }, caption: { color: tokens.color.text.muted, fontSize: tokens.typography.caption.size, lineHeight: 18 }, route: { color: tokens.color.primary.green, fontSize: tokens.typography.metadata.size, fontWeight: '800' }, section: { gap: 8, marginTop: 16 }, rowHeader: { alignItems: 'center', flexDirection: 'row', gap: 12, justifyContent: 'space-between' }, input: { backgroundColor: tokens.color.surface.card, borderColor: tokens.color.border.soft, borderRadius: tokens.radius.row, borderWidth: 1, color: tokens.color.text.primary, fontSize: tokens.typography.body.size, minHeight: 48, paddingHorizontal: 14 }, field: { gap: 6 }, label: { color: tokens.color.text.primary, fontSize: tokens.typography.metadata.size, fontWeight: '700' }, remove: { color: tokens.color.text.muted, fontSize: tokens.typography.caption.size, marginTop: 8 }, summary: { flexDirection: 'row', gap: 8, marginVertical: 12 }, summaryItem: { backgroundColor: tokens.color.surface.card, borderColor: tokens.color.border.soft, borderRadius: tokens.radius.card, borderWidth: 1, flex: 1, minWidth: 0, padding: 10 }, summaryValue: { color: tokens.color.text.primary, fontSize: tokens.typography.body.size, fontWeight: '800' }, segment: { flexDirection: 'row', gap: 6 }, segmentItem: { alignItems: 'center', borderColor: tokens.color.border.soft, borderRadius: tokens.radius.button, borderWidth: 1, flex: 1, justifyContent: 'center', minHeight: 44, paddingHorizontal: 4 }, segmentActive: { backgroundColor: tokens.color.primary.green, borderColor: tokens.color.primary.green }, activeText: { color: '#FFFFFF', fontSize: tokens.typography.caption.size, fontWeight: '800' }, listScreen: { alignSelf: 'stretch', flex: 1, gap: 12, width: '100%' }, flatList: { gap: 10, paddingBottom: 24 }, monthNav: { alignItems: 'center', flexDirection: 'row', justifyContent: 'space-between' }, monthButton: { color: tokens.color.primary.green, fontSize: 32, fontWeight: '700', paddingHorizontal: 12 }, monthLabel: { color: tokens.color.text.primary, fontSize: tokens.typography.body.size, fontWeight: '800' }, week: { flexDirection: 'row' }, weekday: { color: tokens.color.text.muted, flex: 1, fontSize: tokens.typography.caption.size, fontWeight: '700', textAlign: 'center' }, calendar: { flexDirection: 'row', flexWrap: 'wrap' }, dayBlank: { height: 48 }, dayCell: { alignItems: 'center', borderColor: tokens.color.border.soft, borderWidth: 0.5, height: 48, justifyContent: 'center' }, daySelected: { backgroundColor: tokens.color.surface.sage, borderColor: tokens.color.primary.green, borderRadius: tokens.radius.row, borderWidth: 1 }, dayNumber: { color: tokens.color.text.primary, fontSize: tokens.typography.caption.size, fontWeight: '700' }, dayCount: { color: tokens.color.primary.green, fontSize: 10, fontWeight: '800' }, sheetBackdrop: { backgroundColor: 'rgba(31,45,31,0.35)', flex: 1, justifyContent: 'flex-end' }, filterSheet: { backgroundColor: tokens.color.surface.sand, borderTopLeftRadius: tokens.radius.hero, borderTopRightRadius: tokens.radius.hero, gap: 12, padding: tokens.spacing.card } });
